const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const arcPoint = ee.Geometry.Point([2.2950, 48.8738]); // Arc de Triomphe
  const versaillesPoint = ee.Geometry.Point([2.1204, 48.8049]); // Palace of Versailles
  const date = '2024-08-06';

  // 2. Function to get LST from Landsat 8/9
  function getLST(image) {
    // TOA brightness temperature
    const bt = image.select('ST_B10').multiply(0.00341802).add(149.0);

    // NDVI for emissivity
    const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    const pv = ndvi.subtract(0.2).divide(0.5).clamp(0, 1).pow(2);
    const emissivity = pv.multiply(0.004).add(0.986);

    // Convert to Celsius
    const lst = bt.divide(ee.Image.constant(1).add(
      bt.multiply(0.00115).divide(14380)).log().multiply(emissivity))
      .subtract(273.15);

    return lst.rename('LST');
  }

  // 3. Try Landsat 9 first (newest), then Landsat 8
  let lstCol = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.Point([2.2, 48.84])) // Center point between locations

  if (lstCol.size().getInfo() === 0) {
    lstCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(ee.Geometry.Point([2.2, 48.84]))
  }

  // 4. Check if any images found
  const colSize = lstCol.size().getInfo();
  if (colSize === 0) {
    print("2024-08-06 Images: 0");
    print("<answer>C1</answer>");
    return;
  }

  // 5. Process image
  const image = lstCol.first();
  const lst = getLST(image);

  // 6. Extract temperatures with validation
  const arcTemp = lst.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arcPoint.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('LST');

  const versaillesTemp = lst.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: versaillesPoint.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('LST');

  // 7. Check pixel counts for valid data
  const arcCount = lst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arcPoint.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('LST').getInfo();

  const versaillesCount = lst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: versaillesPoint.buffer(1000),
    scale: 1000,
    maxPixels: 1e9
  }).get('LST').getInfo();

  const arcVal = arcTemp.getInfo();
  const versaillesVal = versaillesTemp.getInfo();

  // 8. Validation checks
  print(`2024-08-06 Images: ${colSize}`);
  print(`Arc Pixels: ${arcCount}, Versailles Pixels: ${versaillesCount}`);

  if (arcCount === 0 || versaillesCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  if (arcVal === null || versaillesVal === null || 
      isNaN(arcVal) || isNaN(versaillesVal) ||
      Math.abs(arcVal) > 100 || Math.abs(versaillesVal) > 100) {
    print("<answer>C3</answer>");
    return;
  }

  // 9. Calculate difference and determine answer
  const diff = arcVal - versaillesVal;
  print(`Arc Temp: ${arcVal.toFixed(2)}C, Versailles Temp: ${versaillesVal.toFixed(2)}C`);
  print(`Difference: ${diff.toFixed(2)}C`);

  if (diff >= 5) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
